METHODS = r'''acceptCommission(id){let contract=wayfarerContracts.find(contract=>contract.id===id),region=wayfarerBoardRegion(a);if(!contract||contract.regionId!==region||Object.hasOwn(a.wayfarer.accepted,id))return!1;a.wayfarer.accepted[id]=a.wayfarer.kills[region]??0;a.message={speaker:`Wayfarer Board`,text:`Accepted: ${contract.title}. Return here with the completed report.`};l();z.save();return!0},claimCommission(id){let contract=wayfarerContracts.find(contract=>contract.id===id),region=wayfarerBoardRegion(a),entry=contract&&wayfarerSummary(a,region).contracts.find(entry=>entry.id===id);if(!contract||contract.regionId!==region||!entry?.ready||entry.claimBlocked)return!1;a.wayfarer.claimed.push(id);a.gold+=contract.reward.gold;for(let[itemId,quantity]of Object.entries(contract.reward.items))a.inventory[itemId]=(a.inventory[itemId]??0)+quantity;a.message={speaker:`Wayfarer Board`,text:`${contract.title}: ${contract.completionText}`};l();z.save();return!0},'''


def patch(source):
    labels = []

    def once(old, new, label):
        nonlocal source
        count = source.count(old)
        assert count == 1, f'{label}: expected one anchor, found {count}'
        source = source.replace(old, new, 1)
        labels.append(label)

    once('var he=depthDungeonLayout(expansionWorldLayout(travelMapLayout(j({camp:pe(),works:me()}))));',
         HELPERS+'var he=wayfarerLayout(depthDungeonLayout(expansionWorldLayout(travelMapLayout(j({camp:pe(),works:me()})))));',
         'regional commissions catalog and six local boards without new world destinations')
    once('xp:0,difficulty:dfS??`easy`,sp:{},',
         'xp:0,wayfarer:wayfarerEmpty(),difficulty:dfS??`easy`,sp:{},',
         'new expeditions start with empty commission and bestiary records')
    once('c.sp=sanitizeSpellPractice(n.sp),',
         'c.sp=sanitizeSpellPractice(n.sp),c.wayfarer=sanitizeWayfarer(n.wayfarer),',
         'optional validated version-three commission data preserves older journeys')
    once('e.rewardCommitted=!0;let spoils=encounterSpoils(e.enemies)',
         'e.rewardCommitted=!0;let commissionsReady=wayfarerVictory(a,e);let spoils=encounterSpoils(e.enemies)',
         'record defeated catalog enemies and post-acceptance ordinary kills once on victory')
    once('for(let h of a.heroes)h.level>t[h.id]&&s.push(',
         's.push(...commissionsReady);for(let h of a.heroes)h.level>t[h.id]&&s.push(',
         'victory reports newly ready commissions without paying their rewards automatically')
    once('if(n){if(n.kind===`exit`){travelExit(n)}',
         'if(n){if(n.wayfarerRegion)x(`Wayfarer Board`,`Local keepers post work here. Accept a commission before patrol work, then return with the completed report. Previously copied records and open lifts count.`);else if(n.kind===`exit`){travelExit(n)}',
         'physical board interaction opens the local commission service')
    once('equip(e,t){if(a.mode!==`explore`||a.reward)return!1;',
         METHODS+'equip(e,t){if(a.mode!==`explore`||a.reward)return!1;',
         'board-only accept and whole-reward claim with saved once-only payouts')
    return source, labels
